"""Deliver webhook payloads to subscriber-supplied endpoints."""

import json
import logging
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

REQUEST_TIMEOUT_SECONDS = 5
MAX_RETRIES = 3
BACKOFF_BASE_SECONDS = 1.0


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


@dataclass
class Attempt:
    """The outcome of a single delivery attempt."""

    status: int | None
    error: str | None = None


@dataclass
class DeliveryResult:
    """The outcome of a delivery, including every attempt that was made."""

    status: int | None
    attempts: list[Attempt] = field(default_factory=list)

    @property
    def attempt_count(self) -> int:
        return len(self.attempts)


def _is_retryable(exc: Exception) -> bool:
    if isinstance(exc, urllib.error.HTTPError):
        return exc.code >= 500
    # Any other URLError (DNS failure, connection refused, timeout, ...) or
    # bare timeout/connection error is treated as a transient failure.
    return isinstance(exc, (urllib.error.URLError, TimeoutError, ConnectionError))


def deliver(url: str, payload: dict) -> DeliveryResult:
    """POST a payload to a subscriber endpoint.

    Each attempt is bounded by REQUEST_TIMEOUT_SECONDS. A 5xx response or a
    connection error (timeout, refused connection, DNS failure, ...) is
    retried up to MAX_RETRIES times with exponential backoff; a 4xx response
    is treated as final and returned immediately. The returned DeliveryResult
    carries the outcome of every attempt that was made.
    """
    body = json.dumps(payload).encode()
    delivery_id = new_delivery_id()
    attempts: list[Attempt] = []

    for attempt_number in range(1, MAX_RETRIES + 2):
        request = urllib.request.Request(url, data=body, method="POST")
        request.add_header("X-Signature", sign(json.dumps(payload)))
        logger.info("delivering %s to %s (attempt %d)", delivery_id, url, attempt_number)

        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                attempts.append(Attempt(status=response.status))
                return DeliveryResult(status=response.status, attempts=attempts)
        except urllib.error.HTTPError as exc:
            attempts.append(Attempt(status=exc.code, error=str(exc)))
            if not _is_retryable(exc):
                return DeliveryResult(status=exc.code, attempts=attempts)
        except (urllib.error.URLError, TimeoutError, ConnectionError) as exc:
            attempts.append(Attempt(status=None, error=str(exc)))

        if attempt_number <= MAX_RETRIES:
            backoff = BACKOFF_BASE_SECONDS * (2 ** (attempt_number - 1))
            time.sleep(backoff)

    return DeliveryResult(status=attempts[-1].status, attempts=attempts)

